#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker. (One exception here:
# open_url only prints the address and never launches a browser.)

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL prints the page to visit. This wizard does not open a browser
# itself (changed from the shared library at the owner's request).
open_url() {
  printf '  %s↗ go to this page in your browser:%s\n      %s%s%s\n' "$GREEN" "$RESET" "$BOLD" "$1" "$RESET"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

# This wizard never writes a .env file: the keystore password must not be saved
# anywhere except where the human puts it (a password manager).
ENV_FILE="/dev/null"

[[ -f "android/app/build.gradle.kts" ]] || { echo "Run this from the repo root." >&2; exit 1; }
PACKAGE_NAME=$(grep -oE 'applicationId *= *"[^"]+"' android/app/build.gradle.kts | head -n1 | cut -d'"' -f2)
PACKAGE_NAME=${PACKAGE_NAME:-com.rigcheck.app}
REPO_ROOT=$(git rev-parse --show-toplevel)
ALIAS="upload"
KEYSTORE_NAME="rigcheck-upload.jks"

# Lower-case, forward-slash form of a path, for the "is it inside the repo" test.
_norm() {
  local p="$1"
  if command -v cygpath >/dev/null 2>&1; then p=$(cygpath -m "$p" 2>/dev/null || printf '%s' "$p"); fi
  p=${p//\\//}
  printf '%s' "${p,,}"
}

banner "Android upload keystore: create it, keep it safe, register it with Google"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Find keytool and choose a safe folder"
say "A keystore is one small file that holds the key that signs your Android app."
say "Two things depend on it:"
note "  - Phones only accept an update to an app if it is signed by the same key."
note "  - Google sign-in only works for an app whose package name AND key fingerprint"
note "    Google has on file. A new key means a new fingerprint to register."
say ""
KEYTOOL=""
if command -v keytool >/dev/null 2>&1; then
  KEYTOOL=$(command -v keytool)
else
  for c in "${JAVA_HOME:-}/bin/keytool.exe" "${JAVA_HOME:-}/bin/keytool"; do
    if [[ -n "${JAVA_HOME:-}" && -x "$c" ]]; then KEYTOOL="$c"; break; fi
  done
fi
if [[ -z "$KEYTOOL" ]]; then
  warn "keytool (it ships with Android Studio, in its 'jbr/bin' folder) wasn't found."
  ask KEYTOOL "Paste the full path to keytool.exe:"
fi
[[ -x "$KEYTOOL" ]] || { echo "keytool not found at: $KEYTOOL" >&2; exit 1; }
printf '  %s✓%s using %s\n' "$GREEN" "$RESET" "$KEYTOOL"
say ""
say "Choose a folder for the keystore file. It must be OUTSIDE this repo, so it can"
say "never be committed by accident, and not in a public or shared folder."
note "Example:  G:\\Secrets\\rigcheck   (any folder you control; it is created if missing)"
KEY_DIR=""
while true; do
  ask KEY_DIR "Folder for the keystore:"
  KEY_DIR=${KEY_DIR//\"/}
  KEY_DIR=${KEY_DIR%/}; KEY_DIR=${KEY_DIR%\\}
  if [[ -z "$KEY_DIR" ]]; then warn "Type or paste a folder path."; continue; fi
  if [[ ! "$KEY_DIR" =~ ^([A-Za-z]:|/) ]]; then warn "Use a full path (starting with a drive letter like G:\\ )."; continue; fi
  if command -v cygpath >/dev/null 2>&1; then KEY_DIR=$(cygpath -m "$KEY_DIR"); fi
  n_dir=$(_norm "$KEY_DIR"); n_repo=$(_norm "$REPO_ROOT")
  if [[ "$n_dir/" == "$n_repo/"* ]]; then
    warn "That folder is inside the repo ($REPO_ROOT). Pick one outside it."
    continue
  fi
  break
done
mkdir -p "$KEY_DIR"
KEYSTORE="$KEY_DIR/$KEYSTORE_NAME"
NOTES_FILE="$KEY_DIR/rigcheck-upload-keystore-NOTES.txt"
printf '  %s✓%s keystore will be %s\n' "$GREEN" "$RESET" "$KEYSTORE"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Choose the keystore password"
if [[ -f "$KEYSTORE" ]]; then
  note "A keystore already exists at that path, so it will be reused, not replaced."
  ask_secret STORE_PW "Its password (hidden):"
else
  say "You need ONE password. It protects the file, and the same value is used for"
  say "the key inside it. (Android's build tool will ask for it twice, under"
  say "the names 'store password' and 'key password'; give it the same value.)"
  warn "If this password or the file is lost, you can never publish an update to the"
  warn "same installed app. Testers would have to uninstall and reinstall."
  say "Make it at least 12 characters. Do NOT reuse another password. Better still,"
  say "let your password manager generate one, then paste it here (hidden)."
  while true; do
    ask_secret STORE_PW "New password (hidden):"
    ask_secret STORE_PW2 "Same password again (hidden):"
    if [[ "${#STORE_PW}" -lt 12 ]]; then warn "Too short: use at least 12 characters."; continue; fi
    if [[ "$STORE_PW" != "$STORE_PW2" ]]; then warn "The two entries don't match. Try again."; continue; fi
    break
  done
  unset STORE_PW2
  say ""
  say "Save it in your password manager NOW, as an entry named:"
  note "    RigCheck Android upload keystore   (password = what you just typed;"
  note "    also write the file path and the alias '$ALIAS' in the entry's notes)"
  until confirm "Saved in your password manager?"; do pause "Do that first, then press Enter."; done
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the keystore"
if [[ -f "$KEYSTORE" ]]; then
  note "Already exists, so nothing is created."
else
  say "Creating $KEYSTORE (RSA 2048, valid about 27 years, alias '$ALIAS')..."
  # The password goes to keytool through an environment variable that exists only
  # for this one command, never on the command line.
  UPLOAD_STOREPASS="$STORE_PW" "$KEYTOOL" -J-Duser.language=en -genkeypair -v \
    -keystore "$KEYSTORE" -storetype PKCS12 -alias "$ALIAS" \
    -keyalg RSA -keysize 2048 -validity 10000 \
    -dname "CN=RigCheck Upload" \
    -storepass:env UPLOAD_STOREPASS >/dev/null
  [[ -f "$KEYSTORE" ]] || { echo "keytool did not create the keystore." >&2; exit 1; }
  printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$KEYSTORE"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Read the fingerprint and save a notes file"
say "Checking the password works and reading the key's fingerprints..."
LISTING=$(UPLOAD_STOREPASS="$STORE_PW" "$KEYTOOL" -J-Duser.language=en -list -v \
  -keystore "$KEYSTORE" -alias "$ALIAS" -storepass:env UPLOAD_STOREPASS 2>&1 | tr -d '\r') || {
  echo "keytool could not read the keystore: wrong password, or not a keystore? Re-run and try again." >&2
  exit 1
}
SHA1=$(grep -m1 -E '^[[:space:]]*SHA1:' <<<"$LISTING" | sed -E 's/^[[:space:]]*SHA1:[[:space:]]*//')
SHA256=$(grep -m1 -E '^[[:space:]]*SHA256:' <<<"$LISTING" | sed -E 's/^[[:space:]]*SHA256:[[:space:]]*//')
[[ -n "$SHA1" ]] || { echo "Couldn't read a SHA1 fingerprint from keytool's output." >&2; exit 1; }
unset STORE_PW LISTING
printf '  %s✓%s password works\n\n' "$GREEN" "$RESET"
say "SHA-1 (you register this one with Google):"
printf '      %s%s%s\n' "$BOLD" "$SHA1" "$RESET"
note "SHA-256: $SHA256"
if command -v clip.exe >/dev/null 2>&1; then
  printf '%s' "$SHA1" | clip.exe && note "(The SHA-1 is copied to your clipboard.)"
fi
{
  printf 'RigCheck Android upload keystore: NOTES (no password in this file)\n'
  printf 'Created or checked: %s\n' "$(date +%Y-%m-%d)"
  printf 'Keystore file: %s\n' "$KEYSTORE"
  printf 'Alias: %s\n' "$ALIAS"
  printf 'Package name: %s\n' "$PACKAGE_NAME"
  printf 'SHA-1: %s\n' "$SHA1"
  printf 'SHA-256: %s\n' "$SHA256"
  printf 'Password: in your password manager entry "RigCheck Android upload keystore".\n'
} > "$NOTES_FILE"
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$NOTES_FILE"
pause "Press Enter to continue."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Back it up"
say "One copy of this file is one accident away from gone. Make a second copy"
say "somewhere separate from this computer's drive and not public:"
note "  - an encrypted USB stick, or a private cloud folder only you can open"
note "  - never email it, never put it in the GitHub repo or an issue"
say "Copy these two files from:"
say "    $KEY_DIR"
note "    $KEYSTORE_NAME   and   rigcheck-upload-keystore-NOTES.txt"
until confirm "Second copy made?"; do pause "Do that first, then press Enter."; done

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: register the SHA-1"
say "Google must know this key, or Google sign-in fails on testers' phones."
say "You ADD a new Android client next to the existing one; do not edit the old one."
note "(The old one, 'RigCheck-Android', holds your computer's debug key and stays.)"
open_url "https://console.cloud.google.com/auth/clients"
note "Use the same Google Cloud project that holds the Web client used for RigCheck."
note "If that page looks different, use APIs & Services > Credentials instead."
step "Create client (or: Create credentials > OAuth client ID)."
step "Application type:  Android"
step "Name:  RigCheck-Android-beta"
step "Package name:  $PACKAGE_NAME"
step "SHA-1 certificate fingerprint:  $SHA1"
step "Leave 'Enable Custom URI scheme' and the other options as they are. Create."
note "You don't copy anything from this client. Google can take a few minutes, and"
note "sometimes a few hours, before sign-in works with a new fingerprint."
pause "Done? Press Enter."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: let your testers sign in with Google"
say "While the consent screen is in 'Testing' mode, only Google accounts you list"
say "as test users can use Continue with Google. (Testers who sign up with an email"
say "and password are not affected.)"
open_url "https://console.cloud.google.com/auth/audience"
note "If that page looks different, try APIs & Services > OAuth consent screen."
step "Look at 'Publishing status'."
step "If it says Testing: under 'Test users', Add users, and enter each tester's Gmail."
step "If it says In production: nothing to do here."
pause "Done? Press Enter."

finish
say "Keystore:   $KEYSTORE"
say "Alias:      $ALIAS     Package: $PACKAGE_NAME"
say "SHA-1:      $SHA1"
say ""
say "Still to do (not part of this wizard):"
note "  - The beta build ticket will ask for the keystore path, the alias and the"
note "    password. Keep those in your user-level Gradle properties file, outside the repo."
note "  - Once there is a signed APK, confirm it carries this key:"
note "      keytool -printcert -jarfile <the apk>     (the SHA1 line must match the one above)"
note "  - If the app goes on Google Play with Play app signing, Google re-signs it with a"
note "    different key: add that SHA-1 as one more Android client at that time."
# ──────────────────────────────────────────────────────────────────────────
